mapper.select:
SELECT task_id, activity_name, group_type, task_name, task_date, service_time, location, quota_count, enrolled_count, status, description, dance_class_name, created_at
FROM volunteer_task
WHERE task_id = #{taskId}

mapper.update:
UPDATE volunteer_task
SET enrolled_count = enrolled_count + 1
WHERE task_id = #{taskId}
